using System.Windows; using System.Windows.Controls; namespace VishalXOpt.UI.Controls; public partial class GaugeControl:UserControl{ public GaugeControl(){InitializeComponent();} public static readonly DependencyProperty ValueProperty=DependencyProperty.Register(nameof(Value),typeof(double),typeof(GaugeControl),new PropertyMetadata(0d,OnChanged)); public static readonly DependencyProperty LabelProperty=DependencyProperty.Register(nameof(Label),typeof(string),typeof(GaugeControl),new PropertyMetadata("VALUE",OnChanged)); public double Value{get=> (double)GetValue(ValueProperty);set=>SetValue(ValueProperty,value);} public string Label{get=>(string)GetValue(LabelProperty);set=>SetValue(LabelProperty,value);} static void OnChanged(DependencyObject d,DependencyPropertyChangedEventArgs e){var c=(GaugeControl)d;c.ValueText.Text=$"{c.Value:0}%";c.LabelText.Text=c.Label;} }